import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Navbar from './components/Navbar';
import HomePage from './pages/HomePage';
import ProductListPage from './pages/ProductListPage';
import ProductDetailPage from './pages/ProductDetailPage';
import CartPage from './pages/CartPage';
import CheckoutPage from './pages/CheckoutPage';
import LoginPage from './pages/LoginPage';
import OrdersPage from './pages/OrdersPage';
import { getOrders } from './services/api'; // Import the API utility for fetching orders

function App() {
    const [cart, setCart] = useState([]);
    const [user, setUser] = useState(null); // Manage logged-in user state
    const [orders, setOrders] = useState([]); // Store user orders
    const [isLoading, setIsLoading] = useState(false); // Manage loading state

    // Handle login and set user
    const handleLogin = (userData) => {
        setUser(userData);
        localStorage.setItem('token', userData.token); // Save token in localStorage
    };

    // Handle logout
    const handleLogout = () => {
        setUser(null);
        setCart([]);
        localStorage.removeItem('token'); // Clear token from localStorage
    };

    // Fetch orders when the user logs in
    useEffect(() => {
        const fetchUserOrders = async () => {
            if (user) {
                setIsLoading(true);
                try {
                    const fetchedOrders = await getOrders();
                    setOrders(fetchedOrders);
                } catch (error) {
                    console.error('Failed to fetch orders:', error.message);
                } finally {
                    setIsLoading(false);
                }
            }
        };

        fetchUserOrders();
    }, [user]);

    // Clear the cart
    const handleClearCart = () => {
        setCart([]);
    };

    return (
        <Router>
            <Navbar user={user} onLogout={handleLogout} cartCount={cart.length} />
            <Routes>
                <Route path="/" element={<HomePage />} />
                <Route path="/products" element={<ProductListPage />} />
                <Route path="/products/:id" element={<ProductDetailPage />} />
                <Route
                    path="/cart"
                    element={<CartPage cart={cart} onClearCart={handleClearCart} />}
                />
                <Route
                    path="/checkout"
                    element={
                        user ? (
                            <CheckoutPage cart={cart} onClearCart={handleClearCart} />
                        ) : (
                            <Navigate to="/login" />
                        )
                    }
                />
                <Route
                    path="/login"
                    element={
                        user ? <Navigate to="/" /> : <LoginPage onLogin={handleLogin} />
                    }
                />
                <Route
                    path="/orders"
                    element={
                        user ? (
                            <OrdersPage orders={orders} isLoading={isLoading} />
                        ) : (
                            <Navigate to="/login" />
                        )
                    }
                />
            </Routes>
        </Router>
    );
}

export default App;
